ST.xhtml:p:
FBSlaveAxisAct();

bAxis1ErrorAlarm :=  T1Slave.NCTOPLC.POWERPOSWARN OR T1Slave.NCTOPLC.POWERNEGWARN 
     OR T1Slave.NCTOPLC.ERRORCODE <>0;


  IF bAxis1ErrorAlarm AND g_bPlcResetBuffer THEN
    T1SlaveReset.Execute := TRUE;
  ELSE
    T1SlaveReset.Execute := FALSE;   
  END_IF;

  bAxis2ErrorAlarm :=  T2Slave.NCTOPLC.POWERPOSWARN OR T2Slave.NCTOPLC.POWERNEGWARN 
     OR T2Slave.NCTOPLC.ERRORCODE <>0;


  IF bAxis2ErrorAlarm AND g_bPlcResetBuffer THEN
    T2SlaveReset.Execute := TRUE;
  ELSE
    T2SlaveReset.Execute := FALSE;   
  END_IF;

  bAxis3ErrorAlarm :=  T3Slave.NCTOPLC.POWERPOSWARN OR T3Slave.NCTOPLC.POWERNEGWARN 
     OR T3Slave.NCTOPLC.ERRORCODE <>0;


  IF bAxis3ErrorAlarm AND g_bPlcResetBuffer THEN
    T3SlaveReset.Execute := TRUE;
  ELSE
    T3SlaveReset.Execute := FALSE;   
  END_IF;
